import java.util.*; public class Week02Problem05 {public static void main(String[] z){Scanner s=new Scanner(System.in).useDelimiter("\\A");String t=s.hasNext()?s.next():"";Set<String> stop=new HashSet<>(Arrays.asList("the","was","and","a","is","of","in"));Map<String,Integer> m=new HashMap<>();for(String w:t.toLowerCase().split("\\s+")){w=w.replaceAll("^[.,]+|[.,]+$","");if(!w.isEmpty()&&!stop.contains(w))m.put(w,m.getOrDefault(w,0)+1);}List<Map.Entry<String,Integer>> a=new ArrayList<>(m.entrySet());a.sort((u,v)->u.getValue().equals(v.getValue())?u.getKey().compareTo(v.getKey()):Integer.compare(v.getValue(),u.getValue()));for(Map.Entry<String,Integer> e:a)System.out.println(e.getKey()+" "+e.getValue());}}